INSERT INTO cards (term, definition, hint, image, image_fit) VALUES
  ('Proteiny', 'bílkoviny, organické látky složené z aminokyselin. Tvoří například svaly, enzymy a protilátky a mají stavební i funkční význam.', NULL, NULL, NULL),
  ('Lipidy', 'tuky a další látky, které slouží jako zásoba energie, tvoří součást buněčných membrán a chrání orgány.', NULL, NULL, NULL),
  ('Nukleové kyseliny', 'organické látky, které uchovávají a přenášejí genetickou informaci. Patří mezi ně DNA a RNA.', NULL, NULL, NULL),
  ('Sacharidy', 'organické látky, které slouží hlavně jako zdroj energie, případně jako zásobní nebo stavební látky. Patří sem například cukry a škrob.', NULL, NULL, NULL),
  ('Prokaryotická buňka', 'buňka bez pravého jádra. Její DNA se nachází volně v cytoplazmě. Typická je pro bakterie a archea.', NULL, NULL, NULL),
  ('Eukaryotická buňka', 'buňka s pravým jádrem, ve kterém je uložena většina DNA, a s membránovými organelami.', NULL, NULL, NULL),
  ('Rostlinná buňka', 'eukaryotická buňka, která má buněčnou stěnu, chloroplasty a velkou vakuolu.', NULL, NULL, NULL),
  ('Živočišná buňka', 'eukaryotická buňka bez buněčné stěny a chloroplastů. Má buněčnou membránu a různé organely.', NULL, NULL, NULL),
  ('Cytoplazma', 'prostředí uvnitř buňky, ve kterém jsou uloženy buněčné struktury a probíhá mnoho chemických reakcí.', NULL, NULL, NULL),
  ('Mitochondrie', 'buněčná organela, ve které probíhá buněčné dýchání a vzniká většina ATP využitelného pro činnost buňky.', NULL, NULL, NULL),
  ('Jádro', 'buněčná organela eukaryotických buněk, která obsahuje většinu DNA a řídí činnost buňky prostřednictvím genetické informace.', NULL, NULL, NULL),
  ('Chloroplasty', 'organely rostlinných buněk a řas, ve kterých probíhá fotosyntéza. Obsahují chlorofyl.', NULL, NULL, NULL),
  ('Bičík', 'dlouhý výběžek buňky, který umožňuje její pohyb.', NULL, NULL, NULL),
  ('Brvy', 'krátké, obvykle početné výběžky buňky, které umožňují pohyb buňky nebo posouvání látek po jejím povrchu.', NULL, NULL, NULL),
  ('Organela', 'specializovaná struktura uvnitř buňky, která plní určitou funkci.', NULL, NULL, NULL),
  ('Organické látky', 'látky založené na uhlíku, které tvoří základní součást živých organismů. Patří sem například sacharidy, lipidy, proteiny a nukleové kyseliny.', NULL, NULL, NULL),
  ('Anorganické látky', 'látky, které se běžně neřadí mezi organické. Patří sem například voda, kyslík, oxid uhličitý a minerální soli.', NULL, NULL, NULL),
  ('Buněčný cyklus', 'období od vzniku buňky do jejího dalšího rozdělení. Zahrnuje růst buňky, zdvojení DNA a dělení.', NULL, NULL, NULL),
  ('Mitóza', 'rozdělení jádra, při kterém vznikají dvě geneticky zpravidla shodná jádra se stejným počtem chromozomů jako původní jádro.', NULL, NULL, NULL),
  ('Meióza', 'dělení jádra, při kterém vznikají haploidní buňky s polovičním počtem chromozomů. Je důležitá při vzniku pohlavních buněk.', NULL, NULL, NULL),
  ('Cytokineze', 'rozdělení cytoplazmy mateřské buňky, kterým se dokončuje vznik dceřiných buněk.', NULL, NULL, NULL),
  ('Diploidní buňka', 'buňka se dvěma sadami chromozomů, označuje se 2n. U člověka má obvykle 46 chromozomů.', NULL, NULL, NULL),
  ('Haploidní buňka', 'buňka s jednou sadou chromozomů, označuje se n. U člověka mají pohlavní buňky 23 chromozomů.', NULL, NULL, NULL),
  ('Autotrofní organismus', 'organismus, který si vytváří organické látky z anorganických látek, například rostlina při fotosyntéze.', NULL, NULL, NULL),
  ('Heterotrofní organismus', 'organismus, který získává organické látky a energii z jiných organismů nebo jejich produktů.', NULL, NULL, NULL),
  ('Chromozom', 'struktura tvořená DNA a bílkovinami, která nese genetickou informaci.', NULL, NULL, NULL),
  ('Gameta', 'pohlavní buňka s haploidním počtem chromozomů, například spermie nebo vajíčko.', NULL, NULL, NULL),
  ('Zygota', 'buňka vzniklá splynutím dvou gamet při oplození. Obvykle je diploidní.', NULL, NULL, NULL),
  ('Virus', 'nebuněčná částice tvořená genetickou informací a bílkovinným obalem, která se může množit pouze uvnitř hostitelské buňky.', NULL, NULL, NULL),
  ('Bakterie', 'jednobuněčný prokaryotický organismus, který nemá pravé jádro. Některé bakterie jsou užitečné, jiné způsobují nemoci.', NULL, NULL, NULL),
  ('Stélka', 'tělo některých organismů, například řas a lišejníků, které není rozlišené na pravé kořeny, stonky a listy.', NULL, NULL, NULL),
  ('Pletivo', 'soubor buněk podobného původu a funkce, které společně plní určitou úlohu v těle rostliny.', NULL, NULL, NULL),
  ('Rodozměna', 'střídání dvou generací v životním cyklu rostlin: pohlavní generace (gametofytu) a nepohlavní generace (sporofytu).', NULL, NULL, NULL),
  ('Výtrusné rostliny', 'rostliny, které se rozmnožují výtrusy, například mechy a kapradiny. Netvoří semena.', NULL, NULL, NULL),
  ('Semenné rostliny', 'rostliny, které se rozmnožují semeny. Patří sem nahosemenné a krytosemenné rostliny.', NULL, NULL, NULL),
  ('Nahosemenné rostliny', 'semenné rostliny, jejichž vajíčka a později semena nejsou uzavřena v plodu. Patří sem například jehličnany.', NULL, NULL, NULL),
  ('Krytosemenné rostliny', 'semenné rostliny, jejichž vajíčka jsou uzavřena v semeníku a jejichž semena se vyvíjejí v plodu. Většinou vytvářejí květy.', NULL, NULL, NULL),
  ('Taxe', 'usměrněný pohyb celého organismu nebo buňky směrem k určitému podnětu nebo od něj, například pohyb bakterie za živinami.', NULL, NULL, NULL),
  ('Nastie', 'pohyb rostlinného orgánu vyvolaný podnětem, jehož směr nezávisí na směru podnětu, například zavírání listů citlivky.', NULL, NULL, NULL),
  ('Tropismy', 'usměrněné růstové reakce rostlin na podněty, jejichž směr ovlivňuje směr růstu, například růst stonku ke světlu.', NULL, NULL, NULL),
  ('Fotosyntéza', 'proces, při kterém rostliny, řasy a některé bakterie využívají světelnou energii k tvorbě organických látek z oxidu uhličitého a vody. Uvolňuje se při ní kyslík.', NULL, NULL, NULL),
  ('Chlorofyl', 'zelené barvivo, které pohlcuje světelnou energii a umožňuje její využití při fotosyntéze.', NULL, NULL, NULL),
  ('Fotolýza vody', 'štěpení molekul vody působením světelné energie při fotosyntéze. Vzniká kyslík, protony a elektrony.', NULL, NULL, NULL),
  ('Calvinův cyklus', 'soubor reakcí fotosyntézy, při kterých se využívá energie ATP a redukční síla NADPH k zabudování oxidu uhličitého do organických látek.', NULL, NULL, NULL),
  ('NADPH', 'molekula, která přenáší elektrony a vodík a poskytuje redukční sílu například pro Calvinův cyklus při fotosyntéze.', NULL, NULL, NULL);
